/* Cart uses current catalog prices; browser storage contains only IDs, sizes, quantities. */
let cart=read('velour-cart',[]);if(!Array.isArray(cart))cart=[];
function validCart(){cart=cart.filter(item=>item&&typeof item.id==='string'&&typeof item.size==='string'&&Number.isInteger(item.qty)&&item.qty>0&&item.qty<=20&&products.some(p=>p.id===item.id&&p.sizes.split(',').map(s=>s.trim()).includes(item.size)));return cart.map(item=>({...item,product:products.find(p=>p.id===item.id)}))}
function cartSubtotal(){return validCart().reduce((sum,i)=>sum+i.product.price*i.qty,0)}
function cartTotal(){const subtotal=cartSubtotal();return subtotal-(read('velour-promo','')==='WELCOME10'?Math.round(subtotal*.1):0)}
function saveCart(){try{localStorage.setItem('velour-cart',JSON.stringify(cart))}catch{toast('Корзина работает, но браузер не разрешил сохранить её.')}updateCartCount()}
function updateCartCount(){$('#cartCount').textContent=validCart().reduce((sum,i)=>sum+i.qty,0)}
function photoMarkup(p){return `<div class="cart-photo detail-photo"><img src="${esc(p.image)}" alt="Шуба ${esc(p.name)}"></div>`}
function renderCart(){const items=validCart();updateCartCount();$('#cartContents').innerHTML=items.length?`<div class="cart-items">${items.map((item,index)=>`<article class="cart-item">${photoMarkup(item.product)}<div class="cart-item-description"><p class="eyebrow">${esc(item.product.category)}</p><h3>${esc(item.product.name)}</h3><p>${esc(item.product.color)} · Размер ${esc(item.size)}</p><div class="quantity-control"><button data-cart-minus="${index}" aria-label="Уменьшить количество ${esc(item.product.name)}" ${item.qty===1?'disabled':''}>−</button><output aria-label="Количество">${item.qty}</output><button data-cart-plus="${index}" aria-label="Увеличить количество ${esc(item.product.name)}" ${item.qty===20?'disabled':''}>+</button></div></div><div class="cart-item-end"><strong>${money(item.product.price*item.qty)}</strong><button data-cart-remove="${index}" aria-label="Удалить ${esc(item.product.name)} из корзины">Удалить</button></div></article>`).join('')}</div><div class="cart-summary"><div><span>Стоимость моделей</span><span>${money(cartSubtotal())}</span></div><p>Доставка и наличие уточняются при подключении магазина.</p><div class="cart-grand-total"><span>Итого</span><strong>${money(cartTotal())}</strong></div><button class="button dark checkout-button" id="checkoutButton">Перейти к оплате <span>↗</span></button><p class="payment-disclosure">Демонстрационный магазин. Оплата не подключена, списания денег нет.</p></div>`:`<div class="cart-empty"><span class="cart-empty-mark">V</span><h3>Место для вашей истории.</h3><p>Откройте модель, выберите размер<br>и добавьте её в корзину.</p><button class="button dark" id="continueShopping">Выбрать шубу <span>↗</span></button></div>`;if($('#checkoutButton'))$('#checkoutButton').onclick=openPayment;if($('#continueShopping'))$('#continueShopping').onclick=()=>{$('#cartDialog').close();location.hash='collection'}}
$('#cartButton').onclick=()=>{renderCart();$('#cartDialog').showModal()};
$('#cartContents').addEventListener('click',e=>{const button=e.target.closest('[data-cart-minus],[data-cart-plus],[data-cart-remove]');if(!button)return;validCart();const index=Number(button.dataset.cartMinus??button.dataset.cartPlus??button.dataset.cartRemove);if(!cart[index])return;if(button.hasAttribute('data-cart-remove'))cart.splice(index,1);else if(button.hasAttribute('data-cart-plus'))cart[index].qty=Math.min(20,cart[index].qty+1);else cart[index].qty=Math.max(1,cart[index].qty-1);saveCart();renderCart()});
const originalOpenProduct=openProduct;
openProduct=function(id){originalOpenProduct(id);const p=products.find(x=>x.id===id);if(!p)return;const sizes=$('#productDetail .sizes');sizes.insertAdjacentHTML('beforebegin','<p class="choose-size-label">Выберите размер</p>');sizes.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed','false'));sizes.addEventListener('click',e=>{if(e.target.matches('[data-size]')){sizes.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===e.target)));$('#addToCartButton').disabled=false;$('#sizeHint').textContent='Размер '+e.target.textContent+' выбран'}});$('#tryProduct').insertAdjacentHTML('beforebegin','<button class="button dark add-to-cart" id="addToCartButton" disabled>Добавить в корзину <span>+</span></button><p class="size-hint" id="sizeHint" aria-live="polite">Сначала выберите размер</p>');$('#tryProduct').className='text-link secondary-appointment';$('#addToCartButton').onclick=()=>{const selected=sizes.querySelector('.selected');if(!selected)return;const size=selected.textContent.trim();validCart();const existing=cart.find(i=>i.id===id&&i.size===size);if(existing&&existing.qty>=20){toast('В корзине уже 20 экземпляров этой модели и размера.');return}if(existing)existing.qty++;else cart.push({id,size,qty:1});saveCart();$('#productDialog').close();if($('#wishDialog').open)$('#wishDialog').close();renderCart();$('#cartDialog').showModal();toast(p.name+' · размер '+size+' — в корзине')}};
function openPayment(){if(!validCart().length){renderCart();return}$('#cartDialog').close();const count=cart.reduce((s,i)=>s+i.qty,0);$('#paymentContents').innerHTML=`<div class="payment-mode"><span>◈</span><div><strong>Демонстрационный режим</strong><p>Платёжный сервис ещё не подключён. Банковские данные не запрашиваются, деньги не списываются.</p></div></div><div class="payment-order"><span>Товаров в заказе</span><strong>${count}</strong></div><div class="payment-order"><span>Сумма заказа</span><strong>${money(cartTotal())}</strong></div><button class="button dark checkout-button" id="demoPayButton">Оплатить ${money(cartTotal())} · демо <span>↗</span></button><p class="payment-disclosure">Кнопка показывает демонстрационное подтверждение. Заказ не отправляется в магазин.</p><button class="back-to-cart" id="backToCart">← Вернуться в корзину</button>`;$('#paymentDialog').showModal();$('#backToCart').onclick=()=>{$('#paymentDialog').close();renderCart();$('#cartDialog').showModal()};$('#demoPayButton').onclick=()=>{$('#paymentContents').innerHTML='<div class="demo-complete"><span>✓</span><h3>Всё готово к следующему шагу.</h3><p>Демонстрация оформления завершена.<br>Оплата не проводилась, заказ не отправлен.<br>Товары остались в вашей корзине.</p><button class="button dark" id="finishDemo">Продолжить покупки ↗</button></div>';$('#finishDemo').onclick=()=>{$('#paymentDialog').close();location.hash='collection'}}}
updateCartCount();

document.addEventListener('velour:catalog-changed',()=>{saveCart();if($('#cartDialog').open)renderCart()});
